-- 217: Original BrillaPrep WASSCE BrillaPrep transitional Sculpture beta content blueprint questions, part 5.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_217_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_217_guard;
INSERT INTO _migration_217_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_017' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_4' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why are cuts in wood planned with attention to grain direction?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The grain matters only when transparent finish is finally applied","B. Working with supported fibres reduces uncontrolled splitting and tear-out","C. Every cut should oppose rising grain so the edge lifts longer fibres","D. Knots can be treated as if their fibres run parallel to the board"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Wood is directionally structured. Reading grain run-out, knots and checks helps the sculptor choose tool direction, preserve projecting parts and avoid splitting below the planned surface. Therefore the correct answer is B: Working with supported fibres reduces uncontrolled splitting and tear-out.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_4' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_017' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_217_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_018' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_4' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which operation should precede the refinement of small carved details?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Take the transferred outline directly to its final silhouette before establishing the main depth planes","B. Rough, refine and sand each local area to completion before moving to the adjoining mass","C. Remove waste progressively to establish the major masses, silhouette and depth","D. Finish one facial feature as a scale reference before roughing the head, shoulders and body around it"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Primary masses and viewing silhouettes should be established before secondary forms and detail. Progressive removal keeps measurement possible and protects delicate features during heavy work. Therefore the correct answer is C: Remove waste progressively to establish the major masses, silhouette and depth.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_018' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_217_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_019' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_4' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How does a sculptor create convincing high relief without losing the background support?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Carve the deepest undercuts first before locating the main figures","B. Plan depth levels, overlap and selective undercutting while retaining sound attachments to the ground","C. Detach every projecting part so the composition becomes free-standing","D. Keep every form at the same shallow projection from the background"]' AND q.correct_answer IS 'B' AND q.explanation IS 'High relief depends on a controlled hierarchy from background to strongly projecting forms. Major planes come first; overlaps and undercuts are then developed without severing necessary structural bridges. Therefore the correct answer is B: Plan depth levels, overlap and selective undercutting while retaining sound attachments to the ground.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_4' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_019' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_217_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_020' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_4' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is a finishing allowance retained during rough carving?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It allows deep mistakes to be hidden by cutting every surface further back","B. It permits proportion correction and removal of tool marks without undersizing the form","C. It is extra material intended to remain as an accidental ridge","D. It replaces the need to measure the work from several viewpoints"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Roughing tools and heavy cuts are less precise than finishing operations. A controlled margin protects the designed surface until the main proportions are confirmed and fine refinement begins. Therefore the correct answer is B: It permits proportion correction and removal of tool marks without undersizing the form.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_4' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_020' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_017', 'topic_was_sculpture_b004_4', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'Why are cuts in wood planned with attention to grain direction?', 'multiple_choice', NULL, '["A. The grain matters only when transparent finish is finally applied","B. Working with supported fibres reduces uncontrolled splitting and tear-out","C. Every cut should oppose rising grain so the edge lifts longer fibres","D. Knots can be treated as if their fibres run parallel to the board"]', 'B', 'Wood is directionally structured. Reading grain run-out, knots and checks helps the sculptor choose tool direction, preserve projecting parts and avoid splitting below the planned surface. Therefore the correct answer is B: Working with supported fibres reduces uncontrolled splitting and tear-out.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_4', 'Explain', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_018', 'topic_was_sculpture_b004_4', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'Which operation should precede the refinement of small carved details?', 'multiple_choice', NULL, '["A. Take the transferred outline directly to its final silhouette before establishing the main depth planes","B. Rough, refine and sand each local area to completion before moving to the adjoining mass","C. Remove waste progressively to establish the major masses, silhouette and depth","D. Finish one facial feature as a scale reference before roughing the head, shoulders and body around it"]', 'C', 'Primary masses and viewing silhouettes should be established before secondary forms and detail. Progressive removal keeps measurement possible and protects delicate features during heavy work. Therefore the correct answer is C: Remove waste progressively to establish the major masses, silhouette and depth.', 'hard', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_4', 'Identify', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_019', 'topic_was_sculpture_b004_4', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'How does a sculptor create convincing high relief without losing the background support?', 'multiple_choice', NULL, '["A. Carve the deepest undercuts first before locating the main figures","B. Plan depth levels, overlap and selective undercutting while retaining sound attachments to the ground","C. Detach every projecting part so the composition becomes free-standing","D. Keep every form at the same shallow projection from the background"]', 'B', 'High relief depends on a controlled hierarchy from background to strongly projecting forms. Major planes come first; overlaps and undercuts are then developed without severing necessary structural bridges. Therefore the correct answer is B: Plan depth levels, overlap and selective undercutting while retaining sound attachments to the ground.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_4', 'Explain', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_020', 'topic_was_sculpture_b004_4', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'Why is a finishing allowance retained during rough carving?', 'multiple_choice', NULL, '["A. It allows deep mistakes to be hidden by cutting every surface further back","B. It permits proportion correction and removal of tool marks without undersizing the form","C. It is extra material intended to remain as an accidental ridge","D. It replaces the need to measure the work from several viewpoints"]', 'B', 'Roughing tools and heavy cuts are less precise than finishing operations. A controlled margin protects the designed surface until the main proportions are confirmed and fine refinement begins. Therefore the correct answer is B: It permits proportion correction and removal of tool marks without undersizing the form.', 'medium', '3', '3', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_4', 'Explain', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-visual-arts-beta-004', 'automated_beta', 'beta', 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.', 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf', 0, 1 FROM questions WHERE id IN ('q_was_sculpture_b004_017', 'q_was_sculpture_b004_018', 'q_was_sculpture_b004_019', 'q_was_sculpture_b004_020');
DELETE FROM _migration_217_guard;
